<?php $ts=app(\App\Engines\Builder\Services\TemplateService::class); $bad=[]; foreach(glob(storage_path("templates/*/manifest.json")) as $mf){ $slug=basename(dirname($mf)); $ind=$ts->industryOf($slug); if(!is_file(storage_path("templates/$ind/template.html"))) $bad[$ind][]=$slug; } echo json_encode($bad).PHP_EOL; foreach(array_keys($bad) as $ind){ echo $ind." pages=".count(\App\Engines\Builder\Support\BuilderCapabilities::pages($ind))." sections=".count(\App\Engines\Builder\Support\BuilderCapabilities::sections($ind)).PHP_EOL; } $genA=0;$genB=0; foreach(glob(storage_path("templates/*/manifest.json")) as $mf){ $m=json_decode(file_get_contents($mf),true); $slug=basename(dirname($mf)); if(($m["design"]["generator"]??"")!=="" || isset($m["design"]["generated"])) { $genB++; } else { $genA++; } } echo "genA=$genA genB=$genB total=".($genA+$genB).PHP_EOL; echo "describe=".strlen(\App\Engines\Builder\Support\BuilderCapabilities::describe("pet_services")).PHP_EOL; echo "pages(consulting)=".json_encode(array_map(fn($x)=>$x["slug"],\App\Engines\Builder\Support\BuilderCapabilities::pages("consulting"))).PHP_EOL;
